begin;
select set_config('exp.a',gen_random_uuid()::text,true),set_config('exp.b',gen_random_uuid()::text,true),set_config('exp.p',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('exp.a')::uuid,'expiry-a@example.invalid'),(current_setting('exp.b')::uuid,'expiry-b@example.invalid');
select set_config('request.jwt.claims',json_build_object('sub',current_setting('exp.a'),'role','authenticated')::text,true);set local role authenticated;
insert into public.products(id,name,barcode,sale_price,expiry_date) values(current_setting('exp.p')::uuid,'Expired%_literal','00123',1500,(statement_timestamp() at time zone 'Asia/Baghdad')::date-1);
insert into public.products(name,sale_price,expiry_date) values('Today',1,(statement_timestamp() at time zone 'Asia/Baghdad')::date),('Soon',1,(statement_timestamp() at time zone 'Asia/Baghdad')::date+5),('Later',1,(statement_timestamp() at time zone 'Asia/Baghdad')::date+31),('Empty expired',1,(statement_timestamp() at time zone 'Asia/Baghdad')::date-2),('No date',1,null);
select public.post_purchase(gen_random_uuid(),(select jsonb_agg(jsonb_build_object('product_id',id,'quantity_units',1000,'unit_cost',1)) from public.products where name in ('Expired%_literal','Today','Soon','Later')),'','','');
do $$declare v jsonb;n bigint;begin
 select count(*) into n from public.stock_movements;
 v:=public.get_expiry_report();if v->>'count'<>'1' or v#>>'{rows,0,id}'<>current_setting('exp.p') or v#>>'{rows,0,stage}'<>'expired' or v#>>'{rows,0,quantity_units}'<>'1000' or v#>>'{counts,expired}'<>'1' then raise exception 'expired report wrong';end if;
 v:=public.get_expiry_report('today',30,'',false);if v->>'count'<>'1' or v#>>'{rows,0,days_left}'<>'0' then raise exception 'today boundary wrong';end if;
 v:=public.get_expiry_report('upcoming',7,'',false);if v->>'count'<>'1' or v#>>'{rows,0,days_left}'<>'5' then raise exception 'upcoming window wrong';end if;
 v:=public.get_expiry_report('all',30,'',false);if v->>'count'<>'4' then raise exception 'all filter wrong';end if;
 v:=public.get_expiry_report('expired',30,'',true);if v->>'count'<>'2' or v#>>'{rows,0,name}'<>'Empty expired' then raise exception 'empty stock or sort wrong';end if;
 v:=public.get_expiry_report('expired',30,'%_',false);if v->>'count'<>'1' then raise exception 'literal query wrong';end if;
 v:=public.export_owner_data();if not exists(select 1 from jsonb_array_elements(v#>'{tables,products}') r where r->>'id'=current_setting('exp.p') and r->>'expiry_date'=((statement_timestamp() at time zone 'Asia/Baghdad')::date-1)::text) then raise exception 'owner export omitted date';end if;
 begin update public.products set expiry_date=date '1800-01-01' where id=current_setting('exp.p')::uuid;raise exception 'invalid date allowed';exception when check_violation then null;end;
 update public.products set expiry_date=null where id=current_setting('exp.p')::uuid;
 v:=public.get_expiry_report();if v->>'count'<>'0' then raise exception 'cleared expiry still shown';end if;
 if (select count(*) from public.stock_movements)<>n then raise exception 'expiry changed stock';end if;
 begin perform public.get_expiry_report('bad');raise exception 'bad mode allowed';exception when raise_exception then if sqlerrm<>'expiry_invalid_filters' then raise;end if;end;
end $$;
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('exp.b'),'role','authenticated')::text,true);set local role authenticated;
do $$declare v jsonb;n bigint;begin v:=public.get_expiry_report('all',30,'',true);if v->>'count'<>'0' then raise exception 'other owner leaked';end if;update public.products set expiry_date=current_date where id=current_setting('exp.p')::uuid;get diagnostics n=row_count;if n<>0 then raise exception 'other owner edited';end if;end $$;
insert into public.products(name,sale_price,expiry_date) select 'Cap '||g,1,(statement_timestamp() at time zone 'Asia/Baghdad')::date-1 from generate_series(1,5001) g;
do $$declare v jsonb;begin begin perform public.get_expiry_report('all',30,'',true);raise exception 'truncation allowed';exception when raise_exception then if sqlerrm<>'expiry_too_many_rows' then raise;end if;end;v:=public.get_expiry_report('all',30,'Cap 5001',true);if v->>'count'<>'1' then raise exception 'cap recovery wrong';end if;end $$;
reset role;select set_config('request.jwt.claims','{}',true);set local role authenticated;
do $$begin begin perform public.get_expiry_report();raise exception 'no UID allowed';exception when raise_exception then if sqlerrm<>'expiry_auth_required' then raise;end if;end;end $$;
reset role;set local role anon;
do $$begin begin perform public.get_expiry_report();raise exception 'anon allowed';exception when insufficient_privilege then null;end;end $$;
reset role;
select 'PASS: expiry date grants/checks, Baghdad day boundaries, filters, stock exclusion, export inclusion, row cap, no stock mutation and owner/anon isolation' verification;
rollback;
